    // succeeding, mirroring the Contents API 409 dance between concurrent legs.
    var state = { puts: 0, failed: 0, commands: [] };
    return {
        state: state,
        exec: function (args) {
            var cmd = String((args && args.command) || args || '');
            state.commands.push(cmd);
            if (cmd.indexOf('-X PUT') !== -1) {
