    var at = String((state && state.tick && state.tick.at) || '');
    // '2026-09-23T22:35:55.658Z' → '20260923-2235' (pure string surgery)
    return at.slice(0, 10).replace(/-/g, '') + '-' + at.slice(11, 16).replace(':', '');
